from collections import deque

def round_robin(jobs, q):
    rest = dict(jobs)
    warte = deque(n for n, _ in jobs)
    t, ende = 0, {}
    while warte:
        n = warte.popleft()
        lauf = min(q, rest[n])
        t += lauf
        rest[n] -= lauf
        if rest[n] > 0:
            warte.append(n)
        else:
            ende[n] = t
    return ende

jobs = [("A", 6), ("B", 3),
        ("C", 1), ("D", 4)]
print(round_robin(jobs, 2))
# {'C': 5, 'B': 10, 'D': 12, 'A': 14}
